from format_lecon import Lesson,paras,table,steps
from medicaments import tepezza,methylpred
l=Lesson('Orbitopathie dysthyroïdienne',8)
l.add('L’{orbitopathie dysthyroïdienne est une maladie inflammatoire de l’orbite}. Elle touche les muscles oculomoteurs et les tissus orbitaires. Le strabisme résulte souvent d’une restriction mécanique.',paras('L’Hôpital ophtalmique Jules-Gonin décrit une inflammation des muscles et des tissus autour de l’œil, fréquemment associée à une maladie thyroïdienne. Rétraction palpébrale, exophtalmie, sécheresse et diplopie peuvent coexister.', 'L’activité inflammatoire, la gravité et le retentissement fonctionnel sont des dimensions distinctes. Une limitation résiduelle peut persister après la phase active. Une maladie thyroïdienne équilibrée ne suffit pas à exclure une orbitopathie.'),(11,12))
l.add('Le {contexte associe auto-immunité thyroïdienne et facteurs modifiables}. Le tabagisme favorise une évolution défavorable. Aucun taux suisse spécifique au strabisme restrictif n’est établi ici.',paras('La maladie de Graves est le contexte habituel, mais l’atteinte oculaire peut nécessiter une exploration même sans hyperthyroïdie évidente. EUGOGO recommande notamment une imagerie devant exophtalmie unilatérale ou très asymétrique et devant contexte euthyroïdien à sérologie normale.', 'L’arrêt du tabac et le maintien de l’euthyroïdie sont des objectifs majeurs. Le choix du traitement thyroïdien prend en compte l’activité oculaire et le risque d’aggravation après iode radioactif.', 'Les recommandations européennes de 2021 constituent une base de stratégie. La notice suisse TEPEZZA de mars 2026 apporte une donnée réglementaire plus récente ; elle évite de considérer cette option comme absente de Suisse sur la seule base d’un ancien document.'),(11,12,22))
l.add('La {restriction musculaire et l’encombrement orbitaire expliquent les risques}. Les muscles épaissis limitent les mouvements. L’apex orbitaire peut comprimer le nerf optique.',table(['Mécanisme','Examen utile','Conséquence thérapeutique'],[['Inflammation des muscles et tissus orbitaires.','Douleur, rougeur, œdème et score d’activité.','Discuter une immunomodulation selon activité et gravité.'],['Restriction puis fibrose musculaire.','Mesures de diplopie, ductions et bilan orthoptique.','Prismes sélectionnés ou chirurgie lorsque la maladie est stable.'],['Encombrement de l’apex.','Acuité, couleurs, pupilles, champ visuel et imagerie.','Rechercher une neuropathie optique nécessitant un traitement urgent.'],['Rétraction palpébrale et exposition cornéenne.','Fermeture palpébrale et examen de la cornée.','Lubrifier et protéger ; traiter immédiatement une menace cornéenne.']])+paras('Une forte exophtalmie et une neuropathie ne sont pas synonymes. L’évaluation visuelle doit être menée même si l’apparence externe semble modérée. La correction de l’hyperthyroïdie n’efface pas automatiquement la fibrose ni la diplopie.'),(11,12))
l.add('La {priorité est de rechercher une menace pour la vision}. Baisse d’acuité, altération des couleurs ou atteinte cornéenne sont des alarmes. Une suspicion de neuropathie optique relève d’un avis immédiat.',paras('EUGOGO définit les formes menaçant la vision par neuropathie optique dysthyroïdienne et/ou atteinte cornéenne destructrice. Une fermeture palpébrale insuffisante peut provoquer une exposition sévère. Une subluxation récente du globe est aussi une urgence.', 'L’absence de douleur intense ou un faible score inflammatoire ne remplace pas l’examen fonctionnel. Une baisse visuelle doit être expliquée et ne doit pas être attribuée d’emblée à la sécheresse.', 'Une exophtalmie aiguë douloureuse, fébrile ou très asymétrique impose d’envisager d’autres causes orbitaires, infectieuses ou vasculaires. Une diplopie récente mérite un bilan même chez un patient déjà suivi pour sa thyroïde.'),(11,12))
l.add('L’{anamnèse précise durée, progression et retentissement}. Rechercher tabagisme, symptômes thyroïdiens et traitements antérieurs. Demander explicitement baisse visuelle et modification des couleurs.',paras('Décrire diplopie intermittente ou constante, regards gênants, douleur spontanée ou lors des mouvements, photophobie et sécheresse. La gêne à la lecture ou à la conduite renseigne sur le handicap au-delà de l’aspect des yeux.', 'Documenter fluctuations thyroïdiennes, iode radioactif, chirurgie, traitements immunologiques et exposition cumulée aux corticoïdes. Rechercher diabète, maladie hépatique, hypertension, infection et risque reproductif avant traitement.', 'Si le téprotumumab est envisagé, interroger sur audition, maladie inflammatoire intestinale et contraception. Une perte auditive préexistante ou une grossesse modifie fortement le choix thérapeutique.'),(11,12,22,23))
l.add('L’{examen mesure activité, gravité et fonction visuelle}. Examiner les deux yeux et comparer aux mesures antérieures. Ne pas limiter le bilan à la saillie des globes.',paras('Mesurer acuité, perception des couleurs, pupilles et, selon le contexte, champ visuel. Examiner cornée, fermeture palpébrale, rétraction, conjonctive et tissus mous. Quantifier exophtalmie, motilité et déviation dans les regards utiles.', 'EUGOGO utilise un score d’activité clinique à sept items, avec une maladie dite active à partir de trois sur sept. Ce score apprécie l’inflammation, pas à lui seul la gravité ni l’absence de neuropathie.', 'Le bilan orthoptique décrit la restriction et la diplopie. Des mesures répétées permettent d’apprécier progression ou stabilité avant chirurgie de réhabilitation. Une anomalie pupillaire, chromatique ou du champ visuel conduit à explorer le nerf optique.'),(11,12))
l.add('Les {formes légères, modérées à sévères et menaçantes sont distinguées}. Chaque forme est aussi évaluée comme active ou inactive. Le traitement dépend de ces deux axes.',paras('7.1. Une forme légère a un retentissement limité ne justifiant habituellement pas une immunomodulation lourde. Les mesures locales et la correction des facteurs de risque sont centrales.', '7.2. Une forme modérée à sévère a un retentissement suffisant pour discuter traitement immunologique lorsqu’elle est active, ou réhabilitation lorsqu’elle est inactive. La diplopie peut en être une composante majeure.', '7.3. Une neuropathie optique ou une atteinte cornéenne destructrice définit une forme menaçant la vision. Cette catégorie impose une stratégie urgente, indépendamment d’un calendrier habituel de consultation.'),(12,))
l.add('Le {diagnostic associe signes orbitaires et contexte thyroïdien}. Le bilan biologique soutient la démarche sans remplacer l’examen. Une présentation atypique demande une imagerie.',paras('Le diagnostic est particulièrement évocateur devant rétraction palpébrale, exophtalmie et restriction associées à une auto-immunité thyroïdienne. TSH, hormones thyroïdiennes et anticorps adaptés caractérisent le contexte endocrinien.', 'Une exophtalmie unilatérale, une douleur inhabituelle ou une sérologie non contributive justifient de rechercher les autres causes orbitaires. Une myasthénie peut coexister avec une maladie thyroïdienne et explique plutôt une fluctuation fatigable sans restriction fixe.', 'L’imagerie et le bilan visuel servent également à rechercher une neuropathie compressive. La normalisation de la biologie thyroïdienne n’est pas un critère suffisant de guérison oculaire.'),(11,12,21))
l.add('Les {examens complémentaires répondent au doute et à la gravité}. L’imagerie décrit muscles, graisse et apex. Elle prépare aussi certaines décisions chirurgicales.',paras('9.a. L’examen ophtalmologique spécialisé et le contexte endocrinien établissent le diagnostic habituel ; aucun chiffre sanguin unique ne remplace cette synthèse.', '9.b. Le bilan thyroïdien et les anticorps sont associés aux mesures de fonction visuelle et d’activité. Avant immunothérapie, compléter le bilan de sécurité propre au médicament.', '9.c. EUGOGO recommande l’IRM orbitaire dans les situations atypiques, très asymétriques, avec suspicion de neuropathie ou euthyroïdie à sérologie normale. Le scanner orbitaire est notamment utilisé avant décompression.', '9.d. Une discordance entre imagerie et baisse visuelle impose une réévaluation spécialisée. Rechercher aussi une autre cause de baisse d’acuité, sans retarder le traitement d’une menace identifiée.')+table(['Constat','Décision'],[['L’apex est encombré et la fonction du nerf optique se dégrade.','Filière urgente de neuropathie dysthyroïdienne.'],['La cornée est exposée ou ulcérée.','Protection et traitement ophtalmologique immédiats selon gravité.'],['L’activité est importante sans menace immédiate.','Traitement spécialisé selon gravité, terrain et préférences.'],['La maladie est inactive avec diplopie stable.','Évaluer prismes et chirurgie de réhabilitation.']]),(11,12,22,23))
l.add('L’{algorithme sépare urgence visuelle et réhabilitation}. Déterminer activité et gravité, puis traiter les facteurs de risque. Choisir une stratégie partagée avec endocrinologie et ophtalmologie.',steps('Tester vision, couleurs, pupilles et cornée pour détecter une menace.', 'Classer la gravité et l’activité, documenter diplopie et qualité de vie.', 'Restaurer et maintenir l’euthyroïdie, soutenir l’arrêt du tabac et protéger la surface oculaire.', 'Discuter immunomodulation si la forme active le justifie, avec bilan de sécurité.', 'Réserver la correction durable de la diplopie et des paupières à une stratégie coordonnée après stabilisation, sauf urgence spécifique.'),(11,12))
mp=methylpred(l);tp=tepezza(l)
l.add('La {prise en charge associe traitements locaux, médicaux et chirurgicaux}. Les formes actives et les séquelles fibreuses ne se traitent pas de la même manière. La menace visuelle exige une action immédiate.',paras('11.A. Les objectifs sont de préserver la vision, maîtriser l’inflammation et réduire diplopie et retentissement. Lubrifiants, protection nocturne adaptée, arrêt du tabac et équilibre thyroïdien concernent le parcours global.', '11.B. Dans les formes légères actives, EUGOGO discute le sélénium dans les régions déficitaires ; ce n’est pas une supplémentation universelle à prescrire sans contexte. Dans les formes actives modérées à sévères, la stratégie européenne de 2021 privilégie méthylprednisolone intraveineuse et mycophénolate, avec choix individualisé.', '11.B. Les schémas européens et la sécurité suisse des corticoïdes sont distingués ici : '+mp, '11.B. Le téprotumumab dispose d’une indication suisse pour la forme active modérée à sévère adulte. Sa place est discutée selon les objectifs et le terrain : '+tp, '11.B. La radiothérapie orbitaire et d’autres traitements immunologiques sont des options spécialisées dans des situations sélectionnées. Une fois la maladie inactive et stable, prismes et chirurgie peuvent corriger des séquelles ; le parcours chirurgical coordonne décompression, alignement puis paupières selon les besoins.', '11.C. La neuropathie optique est traitée immédiatement dans un centre expérimenté, avec corticothérapie intraveineuse et décompression si réponse insuffisante ou aggravation. Une atteinte cornéenne menaçante requiert une protection ou chirurgie urgente. Une perfusion programmée de téprotumumab ne remplace pas ce parcours.', '11.D. Le suivi mesure vision, couleurs, motilité, diplopie et activité, ainsi que la toxicité des traitements. Adapter travail et déplacements, soutenir le sevrage tabagique et tenir compte du retentissement psychologique de l’apparence et de la vision.'),(11,12,22,23))
l.add('La {prévention repose sur le tabac, l’équilibre thyroïdien et le suivi}. Prévenir l’exposition cornéenne et les complications thérapeutiques. Expliquer les signes de retour urgent.',paras('La prévention primaire vise les facteurs modifiables, particulièrement le tabagisme. Le choix d’un traitement thyroïdien tient compte du risque oculaire ; une prophylaxie liée à l’iode radioactif est une décision endocrinologique individualisée.', 'La prévention secondaire repère baisse visuelle, changement des couleurs et progression de la diplopie. La prévention tertiaire associe réhabilitation, surveillance des effets indésirables et accompagnement fonctionnel.'),(11,12,22,23))
l.add('Les {points clés distinguent inflammation, fibrose et menace visuelle}. Un score d’activité ne remplace pas l’examen du nerf optique. La diplopie peut persister après équilibre thyroïdien.',paras('La restriction mécanique se distingue d’une paralysie et d’une myasthénie. Les traitements dépendent de l’activité et de la gravité. Les notices suisses récentes doivent compléter les recommandations historiques. Une baisse d’audition sous téprotumumab ou une toxicité des corticoïdes impose une réévaluation.'),(11,12,22,23))
l.quiz([('Quel mécanisme explique souvent le strabisme ?','Une restriction des muscles orbitaires inflammatoires puis fibreux.'),('Une thyroïde équilibrée exclut-elle la maladie oculaire ?','Non.'),('Quel facteur modifiable doit être traité ?','Le tabagisme, notamment.'),('Activité et gravité sont-elles identiques ?','Non.'),('Quel seuil EUGOGO définit une activité au score à sept items ?','Au moins trois sur sept.'),('Un faible score exclut-il une neuropathie ?','Non.'),('Une altération des couleurs mérite-t-elle un bilan urgent ?','Oui, surtout avec baisse visuelle.'),('Une lésion cornéenne menaçante attend-elle la stabilisation ?','Non.'),('Quand envisager une chirurgie de réhabilitation ?','Après stabilisation et inactivité, selon le bilan, hors urgence spécifique.'),('Le schéma européen de méthylprednisolone est-il une posologie AIPS spécifique affirmée ici ?','Non ; les sources et leurs champs sont distingués.'),('TEPEZZA est-il indiqué en Suisse pour tous les enfants avec diplopie ?','Non ; l’indication citée concerne les adultes avec maladie active modérée à sévère.'),('Quel effet peut être permanent sous téprotumumab ?','Une perte auditive.'),('La grossesse est-elle compatible avec TEPEZZA ?','Non ; elle est contre-indiquée.'),('Le traitement de la thyroïde suffit-il toujours à corriger la diplopie ?','Non ; les séquelles peuvent nécessiter une prise en charge propre.')],(11,12,22,23))
l.write()
